import{_ as e,o as i,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Habilidades y límite de habilidades","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/characters/skills-and-skillcap.md","filePath":"es/game-design/characters/skills-and-skillcap.md"}'),s={name:"es/game-design/characters/skills-and-skillcap.md"};function o(d,a,r,c,l,m){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="skills-skillcap" tabindex="-1">Habilidades y límite de habilidades <a class="header-anchor" href="#skills-skillcap" aria-label="Enlace permanente a &quot;Habilidades y límite de habilidades&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las preguntas abiertas permanecen Sin resolver. Las decisiones citadas con estado Aceptado conservan su alcance existente. <strong>Implementación/disponibilidad:</strong> no hay cambios en gameplay ni en configuración de ejecución; no se ha establecido que este rediseño esté activo. <strong>Verificación:</strong> revisión documental, no prueba de juego; aquí no se establece la disponibilidad actual. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/characters/skills.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/characters/progression.html">Progresión del personaje</a></p><h2 id="cap-and-normal-maximum" tabindex="-1">Límite y máximo normal <a class="header-anchor" href="#cap-and-normal-maximum" aria-label="Enlace permanente a &quot;Límite y máximo normal&quot;">​</a></h2><p>La dirección es <strong>aproximadamente 700 puntos totales de habilidad</strong>, <strong>100 como máximo normal por habilidad</strong> y <strong>sin progresión ordinaria a 120 prevista</strong>. Son objetivos de diseño con estado Propuesto, no ajustes de ejecución confirmados ni eliminación del soporte heredado para 120. La maestría a 100 no es el inicio de todo el juego avanzado; las <a href="/Syrolands-Public/es/game-design/characters/progression.html#mastery-and-multiple-endgames">aspiraciones a largo plazo</a> se extienden mediante conocimiento y participación.</p><h2 id="desired-skill-gain" tabindex="-1">Aumento de habilidad deseado <a class="header-anchor" href="#desired-skill-gain" aria-label="Enlace permanente a &quot;Aumento de habilidad deseado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rango</th><th>Ritmo (Propuesto)</th><th>Interpretación</th></tr></thead><tbody><tr><td>0–40</td><td>Muy rápido</td><td>Alcanzar pronto una capacidad inicial útil</td></tr><tr><td>40–60</td><td>Rápido</td><td>Competencia relevante para la configuración, posiblemente durante el primer día</td></tr><tr><td>60–80</td><td>Normal</td><td>Progresión normal sustancial</td></tr><tr><td>80–90</td><td>Muy lento</td><td>Pericia</td></tr><tr><td>90–100</td><td>Extremadamente lento</td><td>Maestría significativa</td></tr></tbody></table><p>Las habilidades relevantes podrían llegar aproximadamente a 40–60 durante el primer día según actividad y configuración. Es una aspiración, no una garantía para cada habilidad ni un presupuesto de tiempo fijo. Horas exactas, probabilidades de aumento, frecuencia de intentos y mecánicas contra macros/de rendimientos decrecientes requieren balance y pruebas de juego.</p><p><strong>Conciliación entre lotes:</strong> Batch 01 describía 80–90 como «Lento»; Batch 02 lo describe como «Muy lento». Esta página registra la última propuesta recibida. La fuente anterior permanece intacta y la página de profesiones ahora enlaza aquí. No supone elevar el balance a Aceptado ni implementarlo.</p><h2 id="meaningful-capability-bands" tabindex="-1">Franjas de capacidad significativa <a class="header-anchor" href="#meaningful-capability-bands" aria-label="Enlace permanente a &quot;Franjas de capacidad significativa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Franja aproximada</th><th>Filosofía de capacidad</th></tr></thead><tbody><tr><td>0</td><td>Sin conocimiento significativo de la disciplina salvo que un origen/competencia inicial conceda fundamentos</td></tr><tr><td>1–20 — Novato</td><td>Las acciones básicas y el ciclo principal son utilizables sin un azar extremo de fallo</td></tr><tr><td>20–40 — Competente</td><td>Fundamentos fiables, más información y opciones básicas más amplias</td></tr><tr><td>40–60 — Hábil</td><td>Útil en grupos, apoya una configuración, técnicas/procesos intermedios aprendidos</td></tr><tr><td>60–80 — Profesional</td><td>Habilidad que define al personaje, situaciones avanzadas y eficiencia/consistencia sólidas</td></tr><tr><td>80–90 — Experto</td><td>Contenido/procesos difíciles, capacidad avanzada, interpretación y consistencia sólidas</td></tr><tr><td>90–100 — Maestro</td><td>Máxima competencia técnica, aumentos muy lentos y técnicas avanzadas/maestras aprendidas por separado; conocimiento y reputación siguen incompletos</td></tr></tbody></table><p>Son franjas aproximadas, no límites exactos de desbloqueo. Los extremos compartidos no definen comprobaciones rivales. La habilidad baja debe funcionar; una inversión mayor sigue siendo valiosa. Las habilidades de apoyo y utilidad compiten por el mismo límite que las especializaciones principales.</p><h2 id="difficulty-envelope-and-readable-progression" tabindex="-1">Rango de dificultad y progresión comprensible <a class="header-anchor" href="#difficulty-envelope-and-readable-progression" aria-label="Enlace permanente a &quot;Rango de dificultad y progresión comprensible&quot;">​</a></h2><p>Una habilidad baja debería resolver de forma consistente trabajos de baja dificultad; una habilidad alta amplía el rango cómodo, desafiante y extremo. Eficiencia, calidad, consistencia e información pueden mejorar con la habilidad. Una habilidad de 20 no debería significar fallar el 80% de las acciones rutinarias. No se selecciona una ecuación de probabilidad ni una dificultad universal de tarea.</p><p>El jugador debería poder comprender «¿Qué gano al pasar de 50 a 70?». Una presentación posible muestra capacidades actuales, la siguiente capacidad importante y capacidades avanzadas/maestras, en lugar de solo bonificaciones opacas por punto. El descubrimiento sigue separado: recetas, técnicas ocultas, conocimiento del mundo e interacciones secretas no tienen que revelarse de antemano. Explicar qué hace una habilidad no significa exponer todo lo que existe.</p><h2 id="learning-skills-from-zero-and-teachers" tabindex="-1">Aprender habilidades desde cero y maestros <a class="header-anchor" href="#learning-skills-from-zero-and-teachers" aria-label="Enlace permanente a &quot;Aprender habilidades desde cero y maestros&quot;">​</a></h2><p>Con exactamente 0, un personaje sin fundamentos iniciales generalmente no sabe cómo empezar. Los aprende de una fuente del mundo: maestro NPC, academia, gremio, entrenador o especialista. La instrucción básica puede elevar la habilidad aproximadamente a <strong>5–10</strong> o desbloquear los fundamentos por otro medio; práctica, exploración y uso continúan el desarrollo.</p><p>Esto mantiene relevantes ciudades, instituciones, NPC y exploración. Es una dirección de enseñanza con estado Propuesto, no una barrera universal ya añadida a las comprobaciones de habilidad. Costes, disponibilidad, distribución y prevención de abusos siguen abiertos. Una <a href="/Syrolands-Public/es/game-design/characters/character-creation.html">competencia inicial</a> puede conceder fundamentos conocidos y aproximadamente 20 de habilidad sin ese requisito inicial de maestro.</p><h2 id="reconciliation-and-open-questions" tabindex="-1">Conciliación y preguntas abiertas <a class="header-anchor" href="#reconciliation-and-open-questions" aria-label="Enlace permanente a &quot;Conciliación y preguntas abiertas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Límite / decisión sin resolver</th></tr></thead><tbody><tr><td>Presupuesto exacto de habilidades</td><td>Aproximadamente 700 es la dirección; el límite final, la distribución y los bloqueos siguen sin resolverse</td></tr><tr><td>Listado y metadatos</td><td>La <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">documentación de funciones</a> existente no es una lista exhaustiva. Los metadatos estáticos del servidor aún incluyen Bowcraft/Fletching; <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a> sigue siendo un camino técnico con estado Propuesto. No se elimina, renumera ni convierte nada</td></tr><tr><td>Magia</td><td>El <a href="/Syrolands-Public/es/game-design/magic.html#use-based-gain-and-structured-teaching">entrenamiento mágico</a> tiene bloques ilustrativos de +5 y objetivos de 55–60 el primer día. No son una fórmula general de aumento. Las tareas rutinarias consistentes deben conciliarse con los mínimos para intentar hechizos y una Difficulty extrema falible; la magia no se reescribe silenciosamente</td></tr><tr><td>Batch 01</td><td>La descripción de 80–90 cambia a Muy lento en la última propuesta; todas las reglas de producción/descubrimiento específicas de los oficios permanecen en el <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></td></tr><tr><td>Habilidades de combate</td><td>Revisar después la presión de obligatoriedad sobre Anatomy, Tactics y Healing. La regla de Anatomy aprobada para Stage 2A y las fórmulas de combate permanecen intactas</td></tr><tr><td>Servidor heredado</td><td>Aumentos/límites existentes, validación de creación y mecanismos de límite 120 son brechas de compatibilidad, no decisiones de conservarlos o eliminarlos</td></tr></tbody></table><p>Otras preguntas abiertas: tiempos exactos de aumento; medidas contra macros/rendimientos decrecientes; habilidades con modelos excepcionales de progresión; costes, disponibilidad y abusos de maestros; redistribución/olvido; conversión de personajes heredados si importan los personajes de producción; interfaz para capacidades actuales/siguientes. No se inventa ninguna fórmula ni implementación para resolverlas.</p><h2 id="magic-knowledge-and-practice-—-batch-04" tabindex="-1">Conocimiento mágico y práctica — Batch 04 <a class="header-anchor" href="#magic-knowledge-and-practice-—-batch-04" aria-label="Enlace permanente a &quot;Conocimiento mágico y práctica — Batch 04&quot;">​</a></h2><p>Los <a href="/Syrolands-Public/es/game-design/magic/spell-knowledge.html">Core Patterns</a> separan el conocimiento aprendido de la ejecución de Magery. <a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html">Familiarity</a> es práctica por patrón fuera del límite de habilidades, no una nueva habilidad limitada. Magery 100 sigue siendo maestría técnica bajo la dirección con estado Propuesto sin progresión ordinaria a 120; conocimientos raros, escuelas, variantes, preparación e Inscription amplían la progresión. La conciliación de ritmo/dificultad indicada arriba sigue abierta.</p>',23)])])}const b=e(s,[["render",o]]);export{u as __pageData,b as default};
